{
  "steps": [
    {
      "id": "S1",
      "task_id": "T1",
      "title": "Submit Ethics Application",
      "instruction": "Prepare and submit the application for ethics approval to the relevant ethics board.",
      "expected_result": "Ethics approval is obtained for the use of human specimens."
    },
    {
      "id": "S2",
      "task_id": "T1",
      "title": "Receive Ethics Approval",
      "instruction": "Await and confirm receipt of ethics approval from the ethics board.",
      "expected_result": "Confirmation of ethics approval is received."
    },
    {
      "id": "S3",
      "task_id": "T2",
      "title": "Collect Biopsy Specimens",
      "instruction": "Collect postmortem biopsy specimens from COVID-19 and non-COVID-19 patients.",
      "expected_result": "Biopsy specimens are collected and labeled appropriately."
    },
    {
      "id": "S4",
      "task_id": "T2",
      "title": "Match Control Specimens",
      "instruction": "Ensure proper matching of control specimens with the COVID-19 patient biopsies.",
      "expected_result": "Control specimens are matched and documented."
    },
    {
      "id": "S5",
      "task_id": "T4",
      "title": "Fix Biopsy Specimens",
      "instruction": "Fix the collected lung biopsy specimens in 4% formaldehyde for three hours at room temperature.",
      "expected_result": "Biopsy specimens are fixed and ready for embedding."
    },
    {
      "id": "S6",
      "task_id": "T4",
      "title": "Embed Specimens in Paraffin",
      "instruction": "Embed the fixed biopsies in paraffin following dehydration, clearing, and embedding steps.",
      "expected_result": "Biopsy specimens are embedded in paraffin."
    },
    {
      "id": "S7",
      "task_id": "T4",
      "title": "Cut Tissue Sections",
      "instruction": "Cut 4-µm thick tissue sections using a rotary microtome and place them on Superfrost slides.",
      "expected_result": "Tissue sections are prepared on slides for further processing."
    },
    {
      "id": "S8",
      "task_id": "T5",
      "title": "Remove Paraffin from Slides",
      "instruction": "Rinse the slides in Neo Clear and progressively decrease ethanol concentration to remove paraffin.",
      "expected_result": "Paraffin is removed, and slides are ready for antigen retrieval."
    },
    {
      "id": "S9",
      "task_id": "T5",
      "title": "Perform Antigen Retrieval",
      "instruction": "Immerse slides in antigen retrieval buffer and heat in a sterilizer for the specified time.",
      "expected_result": "Antigen retrieval is completed, and slides are cooled."
    },
    {
      "id": "S10",
      "task_id": "T5",
      "title": "Block Non-Specific Binding",
      "instruction": "Incubate slides with blocking buffer to prevent non-specific binding.",
      "expected_result": "Slides are blocked and ready for primary antibody staining."
    },
    {
      "id": "S11",
      "task_id": "T5",
      "title": "Apply Primary Antibodies",
      "instruction": "Prepare and apply the primary staining mix to the tissue sections, then incubate.",
      "expected_result": "Primary antibodies are bound to the target antigens in the tissue."
    },
    {
      "id": "S12",
      "task_id": "T6",
      "title": "Acquire Images",
      "instruction": "Use fluorescence and confocal microscopy to acquire images of the stained lung sections.",
      "expected_result": "Images of stained sections are captured for analysis."
    },
    {
      "id": "S13",
      "task_id": "T7",
      "title": "Analyze Images for NET Volume",
      "instruction": "Use Imaris software to analyze the acquired images and quantify the volume of NETs.",
      "expected_result": "Quantification of NET volume is completed."
    },
    {
      "id": "S14",
      "task_id": "T8",
      "title": "Scan Lung Sections",
      "instruction": "Use the Nanozoomer system to scan entire lung sections for NET-infiltrating areas.",
      "expected_result": "Lung sections are scanned and ready for further analysis."
    },
    {
      "id": "S15",
      "task_id": "T9",
      "title": "Perform Statistical Analysis",
      "instruction": "Analyze the collected data statistically to determine the significance of findings.",
      "expected_result": "Statistical analysis results are obtained and documented."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "task_id": "T1",
      "title": "Germinate Tomato Seeds",
      "instruction": "Germinate tomato seeds in pots filled with 100% vermiculite under controlled light/dark cycles and temperature.",
      "expected_result": "Tomato seeds successfully germinated and seedlings developed."
    },
    {
      "id": "S2",
      "task_id": "T1",
      "title": "Irrigate Seedlings",
      "instruction": "Irrigate seedlings twice a week with distilled water for one week.",
      "expected_result": "Seedlings are adequately hydrated and ready for nutrient solution application."
    },
    {
      "id": "S3",
      "task_id": "T1",
      "title": "Apply Nutrient Solution",
      "instruction": "Irrigate seedlings twice a week for three weeks with a nutrient solution adjusted to pH 6.0.",
      "expected_result": "Seedlings receive necessary nutrients for optimal growth."
    },
    {
      "id": "S4",
      "task_id": "T3",
      "title": "Divide Tomato Plants",
      "instruction": "Divide 20 uniform tomato plants into two groups: one treated and one control group.",
      "expected_result": "Two groups of tomato plants established for treatment comparison."
    },
    {
      "id": "S5",
      "task_id": "T3",
      "title": "Apply Initial Inhibitor Treatment",
      "instruction": "Treat 21-day-old tomato plants with 2 ml of the inhibitor mix by soil drench.",
      "expected_result": "Inhibitor treatment applied to the first group of plants."
    },
    {
      "id": "S6",
      "task_id": "T3",
      "title": "Apply Subsequent Inhibitor Treatment",
      "instruction": "At 23 days old, treat plants with 4 ml of the inhibitor mix by soil drench.",
      "expected_result": "Second round of inhibitor treatment successfully applied."
    },
    {
      "id": "S7",
      "task_id": "T3",
      "title": "Final Inhibitor Treatment",
      "instruction": "At 25 and 27 days old, treat plants with 8 ml of the inhibitor mix by soil drench.",
      "expected_result": "Final round of inhibitor treatment completed."
    },
    {
      "id": "S8",
      "task_id": "T3",
      "title": "Collect Leaf Samples",
      "instruction": "24 hours after the last treatment, collect the 3rd and 4th true leaves from treated and control plants.",
      "expected_result": "Leaf samples collected and ready for storage."
    },
    {
      "id": "S9",
      "task_id": "T3",
      "title": "Crush Leaf Samples",
      "instruction": "Crush a pool of 10 plants in liquid nitrogen for further analysis.",
      "expected_result": "Plant material prepared for putrescine extraction."
    },
    {
      "id": "S10",
      "task_id": "T6",
      "title": "Measure Biomass",
      "instruction": "Weigh dried plant tissues to determine biomass.",
      "expected_result": "Biomass data collected for analysis."
    },
    {
      "id": "S11",
      "task_id": "T7",
      "title": "Collect Leaf Samples for H2O2 Analysis",
      "instruction": "Collect leaf samples for processing to quantify H2O2 levels.",
      "expected_result": "Leaf samples prepared for H2O2 quantification."
    },
    {
      "id": "S12",
      "task_id": "T8",
      "title": "Extract RNA from Leaf Tissues",
      "instruction": "Extract RNA from collected leaf tissues for gene expression analysis.",
      "expected_result": "RNA samples prepared for qRT-PCR analysis."
    },
    {
      "id": "S13",
      "task_id": "T10",
      "title": "Analyze Hormonal Levels",
      "instruction": "Perform chromatographic analysis of hormones in plant tissues using HPLC.",
      "expected_result": "Hormonal profiles obtained for further investigation."
    },
    {
      "id": "S14",
      "task_id": "T11",
      "title": "Statistical Analysis of Results",
      "instruction": "Analyze experimental data using ANOVA to assess significance across treatments.",
      "expected_result": "Statistical results generated for interpretation."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "task_id": "T1",
      "title": "Inoculate Bacterial Strain",
      "instruction": "Pick a single colony of Salmonella cells expressing pHluorin(M153R)-FliG from an LB agar plate and inoculate it into a glass test tube with 5 mL of LB, shaking at 150 rpm at 30°C overnight.",
      "expected_result": "Overnight culture of Salmonella cells is prepared."
    },
    {
      "id": "S2",
      "task_id": "T1",
      "title": "Transfer Culture to Fresh Medium",
      "instruction": "Transfer 50 µL of the overnight culture to 5 mL of fresh TB and incubate at 30°C with shaking at 150 rpm until the cell density reaches an OD_600 of approximately 1.8.",
      "expected_result": "Fresh culture of Salmonella cells with appropriate density is obtained."
    },
    {
      "id": "S3",
      "task_id": "T1",
      "title": "Centrifuge Cells",
      "instruction": "Transfer 500 µL of the culture to a 1.5 mL microcentrifuge tube and centrifuge at 6,000× g for 2 minutes.",
      "expected_result": "Cell pellet is collected at the bottom of the tube."
    },
    {
      "id": "S4",
      "task_id": "T1",
      "title": "Wash Cell Pellet",
      "instruction": "Discard the supernatant and resuspend the cell pellet in 1.0 mL of motility buffer, then centrifuge again at 6,000× g for 2 minutes.",
      "expected_result": "Cells are washed and resuspended in motility buffer."
    },
    {
      "id": "S5",
      "task_id": "T1",
      "title": "Repeat Washing Steps",
      "instruction": "Repeat the washing process (steps S4) twice to ensure thorough washing of the cells.",
      "expected_result": "Cells are thoroughly washed and ready for resuspension."
    },
    {
      "id": "S6",
      "task_id": "T1",
      "title": "Final Resuspension",
      "instruction": "Resuspend the cells in 500 µL of fresh motility buffer.",
      "expected_result": "Cells are prepared in motility buffer for further experiments."
    },
    {
      "id": "S7",
      "task_id": "T5",
      "title": "Prepare Tunnel Slide",
      "instruction": "Make a tunnel slide by sandwiching double-sided tape between a 24×32 mm coverslip and an 18×18 mm coverslip.",
      "expected_result": "Tunnel slide is prepared for cell observation."
    },
    {
      "id": "S8",
      "task_id": "T5",
      "title": "Add Cell Suspension to Tunnel Slide",
      "instruction": "Add 50 µL of the cell suspension to the tunnel slide and leave for 5 minutes to allow cells to attach.",
      "expected_result": "Cells are attached to the coverslip surface."
    },
    {
      "id": "S9",
      "task_id": "T5",
      "title": "Wash Unbound Cells",
      "instruction": "Wash out unbound cells by supplying 100 µL of motility buffer and absorb the excess with filter paper.",
      "expected_result": "Unbound cells are removed, leaving attached cells for imaging."
    },
    {
      "id": "S10",
      "task_id": "T5",
      "title": "Set Up Fluorescence Microscope",
      "instruction": "Put the sample on a custom-built inverted fluorescence microscope and select a 150× objective with a 1.6x variable lens.",
      "expected_result": "Microscope is set up and ready for imaging."
    },
    {
      "id": "S11",
      "task_id": "T5",
      "title": "Capture Fluorescence Images",
      "instruction": "Switch between 410 and 470 nm excitation filters and capture images of the pHluorin(M153R)-FliG fluorescent spots using the EMCCD camera.",
      "expected_result": "Fluorescence images of Salmonella cells are captured."
    },
    {
      "id": "S12",
      "task_id": "T6",
      "title": "Prepare for pH Measurement",
      "instruction": "Resuspend SJW1368 cells carrying pYVM008 in 500 µL of motility buffer containing 20 µM gramicidin and 20 mM potassium benzoate.",
      "expected_result": "Cells are prepared for in vivo calibration."
    },
    {
      "id": "S13",
      "task_id": "T6",
      "title": "Acquire Ratiometric Fluorescence Images",
      "instruction": "Acquire ratiometric fluorescence images of the cells at external pH values of 6.0, 6.5, 7.0, or 7.5.",
      "expected_result": "Ratiometric fluorescence images are obtained for pH analysis."
    },
    {
      "id": "S14",
      "task_id": "T4",
      "title": "Suspend Purified Proteins",
      "instruction": "Suspend purified pHluorin(M153R)-FliG proteins in motility buffer with distinct pH values ranging from 5.5 to 8.5.",
      "expected_result": "Protein solutions at various pH values are prepared for in vitro calibration."
    },
    {
      "id": "S15",
      "task_id": "T4",
      "title": "Acquire Fluorescence Images of Proteins",
      "instruction": "Add 50 µL of the protein solution to the tunnel slide and acquire fluorescence images excited by 410 and 470 nm at each pH value.",
      "expected_result": "Fluorescence images of pHluorin(M153R)-FliG proteins are captured for calibration."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "task_id": "T1",
      "title": "Sow Seeds",
      "instruction": "Sow common bean ‘Black Valentine’ seeds in plastic pots filled with moistened vermiculite, placing the seeds just under the surface.",
      "expected_result": "Seeds are planted and ready for germination."
    },
    {
      "id": "S2",
      "task_id": "T1",
      "title": "Place Pots in Growth Chamber",
      "instruction": "Put the pots in a tub full of tap water and place them in a growth chamber at 23°C under a 16 h light/8 h dark cycle.",
      "expected_result": "Pots are in the growth chamber, ensuring optimal conditions for seedling growth."
    },
    {
      "id": "S3",
      "task_id": "T1",
      "title": "Water Seedlings",
      "instruction": "Regularly fill the tub with tap water to maintain capillary watering for the seedlings.",
      "expected_result": "Seedlings receive adequate moisture for growth."
    },
    {
      "id": "S4",
      "task_id": "T1",
      "title": "Grow Seedlings",
      "instruction": "Allow seedlings to grow for 10-12 days until primary leaves are fully expanded.",
      "expected_result": "Seedlings develop fully-expanded primary leaves."
    },
    {
      "id": "S5",
      "task_id": "T1",
      "title": "Prepare for Inoculation",
      "instruction": "Place the plants in a dark room at 19°C and 75% relative humidity for 24 hours prior to inoculation.",
      "expected_result": "Plants are acclimated and ready for inoculation."
    },
    {
      "id": "S6",
      "task_id": "T3",
      "title": "Prepare DNA Plasmid Mix",
      "instruction": "Mix the appropriate BPMV plasmids in a microfuge tube with potassium phosphate buffer to create the DNA plasmid mix.",
      "expected_result": "DNA plasmid mix is prepared for inoculation."
    },
    {
      "id": "S7",
      "task_id": "T3",
      "title": "Powder Leaf with Carborundum",
      "instruction": "Powder the upper surface of one primary leaf per plant with carborundum.",
      "expected_result": "Leaf surface is prepared for mechanical inoculation."
    },
    {
      "id": "S8",
      "task_id": "T3",
      "title": "Apply DNA Plasmid Mix",
      "instruction": "Using a pipette, place the DNA plasmid mix on the upper leaf surface at the junction between petiole and blade.",
      "expected_result": "DNA plasmid mix is applied to the leaf surface."
    },
    {
      "id": "S9",
      "task_id": "T3",
      "title": "Rub Leaf Surface",
      "instruction": "Rub the leaf surface with a gloved finger to spread the DNA plasmid mix evenly across the leaf.",
      "expected_result": "DNA plasmid mix is evenly distributed on the leaf surface."
    },
    {
      "id": "S10",
      "task_id": "T3",
      "title": "Rinse Leaf",
      "instruction": "At 3-4 minutes after rubbing, rinse the inoculated leaf with tap water until all carborundum is removed.",
      "expected_result": "Leaf is rinsed clean of carborundum."
    },
    {
      "id": "S11",
      "task_id": "T3",
      "title": "Place Inoculated Plants in Growth Chamber",
      "instruction": "Place the inoculated plants in a greenhouse or growth chamber at 19°C under a 16 h light/8 h dark cycle.",
      "expected_result": "Inoculated plants are in optimal conditions for viral infection."
    },
    {
      "id": "S12",
      "task_id": "T6",
      "title": "Extract Total RNA",
      "instruction": "Extract total RNA from the plant tissues using an appropriate RNA extraction protocol.",
      "expected_result": "Total RNA is isolated from the plant samples."
    },
    {
      "id": "S13",
      "task_id": "T6",
      "title": "Synthesize cDNA",
      "instruction": "Synthesize cDNA from the extracted RNA using reverse transcription.",
      "expected_result": "cDNA is generated for further analysis."
    },
    {
      "id": "S14",
      "task_id": "T6",
      "title": "Analyze Gene Expression",
      "instruction": "Perform semi-quantitative RT-PCR to analyze specific gene expression levels.",
      "expected_result": "Gene expression data is obtained for analysis."
    },
    {
      "id": "S15",
      "task_id": "T5",
      "title": "Visualize GFP Expression",
      "instruction": "Use UV light to visualize GFP expression in the plant tissues.",
      "expected_result": "GFP expression is observed in the tissues under UV light."
    },
    {
      "id": "S16",
      "task_id": "T7",
      "title": "Map R-BPMV Gene",
      "instruction": "Conduct segregation analysis and use linkage mapping software to map the R-BPMV resistance gene.",
      "expected_result": "R-BPMV gene is mapped successfully."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "task_id": "T1",
      "title": "Obtain Ethical Approval",
      "instruction": "Ensure that all necessary ethical approvals are obtained for patient sample collection.",
      "expected_result": "Ethical approval documentation is secured."
    },
    {
      "id": "S2",
      "task_id": "T1",
      "title": "Collect Blood Samples",
      "instruction": "Collect blood samples from patients diagnosed with SARS following the approved ethical guidelines.",
      "expected_result": "Blood samples are collected and labeled appropriately."
    },
    {
      "id": "S3",
      "task_id": "T2",
      "title": "Design Plasmids",
      "instruction": "Design plasmids that include the necessary viral genes, particularly the SARS-CoV S protein.",
      "expected_result": "Plasmid designs are finalized and ready for construction."
    },
    {
      "id": "S4",
      "task_id": "T2",
      "title": "Construct Plasmids",
      "instruction": "Construct the designed plasmids using appropriate molecular biology techniques.",
      "expected_result": "Plasmids containing the viral genes are successfully constructed."
    },
    {
      "id": "S5",
      "task_id": "T3",
      "title": "Culture QT6 Cells",
      "instruction": "Culture QT6 cells in appropriate growth media until they reach the desired confluence.",
      "expected_result": "QT6 cells are ready for transfection."
    },
    {
      "id": "S6",
      "task_id": "T3",
      "title": "Transfect QT6 Cells",
      "instruction": "Transfect QT6 cells with ACE2 plasmid using a suitable transfection reagent.",
      "expected_result": "QT6/ACE2 cells are successfully transfected."
    },
    {
      "id": "S7",
      "task_id": "T4",
      "title": "Prepare for Transfection",
      "instruction": "Subculture 293T/17 cells into 6-well plates to achieve 70-90% confluence.",
      "expected_result": "293T/17 cells are prepared for transfection."
    },
    {
      "id": "S8",
      "task_id": "T4",
      "title": "Transfect 293T Cells",
      "instruction": "Transfect 293T cells with the prepared plasmid constructs using PEI and Opti-MEM.",
      "expected_result": "293T cells are transfected with viral constructs."
    },
    {
      "id": "S9",
      "task_id": "T4",
      "title": "Harvest Viral Supernatant",
      "instruction": "Harvest the supernatant containing viral pseudotype particles after incubation.",
      "expected_result": "Viral supernatant is collected and filtered."
    },
    {
      "id": "S10",
      "task_id": "T4",
      "title": "Store Viral Supernatant",
      "instruction": "Store the filtered viral supernatant at -80°C in aliquots.",
      "expected_result": "Viral supernatant is stored properly for future use."
    },
    {
      "id": "S11",
      "task_id": "T5",
      "title": "Infect QT6/ACE2 Cells",
      "instruction": "Infect QT6/ACE2 cells with the harvested viral vectors.",
      "expected_result": "QT6/ACE2 cells are infected with viral vectors."
    },
    {
      "id": "S12",
      "task_id": "T5",
      "title": "Measure Infectious Units",
      "instruction": "Measure the titer of infectious units using a suitable assay.",
      "expected_result": "Infectious units are quantified."
    },
    {
      "id": "S13",
      "task_id": "T6",
      "title": "Prepare Patient Serum Samples",
      "instruction": "Obtain and prepare patient serum samples for neutralization assays.",
      "expected_result": "Patient serum samples are ready for testing."
    },
    {
      "id": "S14",
      "task_id": "T6",
      "title": "Perform Neutralization Assays",
      "instruction": "Conduct neutralization assays using patient serum samples against live SARS virus.",
      "expected_result": "Neutralization capacity is assessed."
    },
    {
      "id": "S15",
      "task_id": "T7",
      "title": "Prepare Pseudotype Virus",
      "instruction": "Prepare pseudotyped MLV(SARS) virions for neutralization assays.",
      "expected_result": "Pseudotype virus is ready for testing."
    },
    {
      "id": "S16",
      "task_id": "T7",
      "title": "Conduct Neutralization Assays",
      "instruction": "Perform neutralization assays using pseudotyped MLV(SARS) virions and patient serum samples.",
      "expected_result": "Neutralization titers are determined."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "task_id": "T1",
      "title": "Access TCGA Database",
      "instruction": "Navigate to the TCGA database and select the breast cancer dataset.",
      "expected_result": "The breast cancer dataset is accessed for analysis."
    },
    {
      "id": "S2",
      "task_id": "T1",
      "title": "Extract mRNA Levels",
      "instruction": "Collect mRNA levels of MCU and related proteins from the dataset.",
      "expected_result": "mRNA levels of MCU and related proteins are extracted for analysis."
    },
    {
      "id": "S3",
      "task_id": "T1",
      "title": "Analyze Correlation",
      "instruction": "Analyze the correlation of mRNA levels with tumor progression metrics.",
      "expected_result": "Correlation data is generated for further interpretation."
    },
    {
      "id": "S4",
      "task_id": "T2",
      "title": "Select Cell Lines",
      "instruction": "Choose three human metastatic TNBC cell lines for the experiment.",
      "expected_result": "Three TNBC cell lines are selected for treatment."
    },
    {
      "id": "S5",
      "task_id": "T2",
      "title": "Treat with Agonists",
      "instruction": "Treat the selected cell lines with specific agonists to induce cytosolic Ca2+ transients.",
      "expected_result": "Cell lines are treated and prepared for subsequent analysis."
    },
    {
      "id": "S6",
      "task_id": "T3",
      "title": "Prepare siRNA",
      "instruction": "Design and prepare short-interfering RNA (siRNA) targeting MCU for transfection.",
      "expected_result": "siRNA is ready for transfection into TNBC cell lines."
    },
    {
      "id": "S7",
      "task_id": "T3",
      "title": "Transfect Cells",
      "instruction": "Transfect the selected TNBC cell lines with MCU-targeting siRNA.",
      "expected_result": "MCU expression is inhibited in the transfected cell lines."
    },
    {
      "id": "S8",
      "task_id": "T3",
      "title": "Assess Mitochondrial Ca2+ Uptake",
      "instruction": "Evaluate the impact of MCU silencing on mitochondrial Ca2+ uptake in the transfected cells.",
      "expected_result": "Data on mitochondrial Ca2+ uptake is collected for analysis."
    },
    {
      "id": "S9",
      "task_id": "T4",
      "title": "Create Wound",
      "instruction": "Perform a wound healing assay by creating a wound in a confluent monolayer of TNBC cells.",
      "expected_result": "A standardized wound is created in the cell monolayer."
    },
    {
      "id": "S10",
      "task_id": "T4",
      "title": "Monitor Cell Migration",
      "instruction": "Monitor and record the migration of cells into the wound area over time.",
      "expected_result": "Data on cell migration is collected for analysis."
    },
    {
      "id": "S11",
      "task_id": "T5",
      "title": "Prepare Spheroid Culture",
      "instruction": "Initiate spheroid formation by plating MCU-silenced TNBC cells in appropriate conditions.",
      "expected_result": "Spheroids are formed from the cultured cells."
    },
    {
      "id": "S12",
      "task_id": "T5",
      "title": "Evaluate Invasion Potential",
      "instruction": "Assess the invasion potential of the formed spheroids using appropriate assays.",
      "expected_result": "Data on invasion potential is collected for analysis."
    },
    {
      "id": "S13",
      "task_id": "T6",
      "title": "Inject Cells into Mice",
      "instruction": "Inject MCU-deleted MDA-MB-231 cells into SCID mice.",
      "expected_result": "Mice are injected with the cell line for tumor monitoring."
    },
    {
      "id": "S14",
      "task_id": "T6",
      "title": "Monitor Tumor Growth",
      "instruction": "Regularly monitor tumor growth, lymph node infiltration, and metastasis formation in the injected mice.",
      "expected_result": "Data on tumor growth and metastasis is collected."
    },
    {
      "id": "S15",
      "task_id": "T7",
      "title": "Measure NADH and NADPH Levels",
      "instruction": "Measure cellular and mitochondrial NADH and NADPH levels in MCU-silenced cells.",
      "expected_result": "Data on NADH and NADPH levels is collected for analysis."
    },
    {
      "id": "S16",
      "task_id": "T7",
